mapper.select:
SELECT id, account_id, type, credential_data, status, created_at, rotated_at
FROM ainer_identity_credential
WHERE account_id = #{accountId}
  AND type = #{type}
  AND status = 'ACTIVE'
LIMIT 1

mapper.update:
UPDATE ainer_identity_credential
SET status = 'REVOKED', rotated_at = #{rotatedAt}
WHERE account_id = #{accountId}
  AND type = #{type}
  AND status = 'ACTIVE'
